}
import { Box3, Group, LoadingManager, Material, Matrix4, Mesh, Texture } from "three";
import { GLTFLoader } from "three/examples/jsm/loaders/GLTFLoader.js";

export class ModelParseError extends Error {
  constructor(message: string) {
    super(message);
    this.name = "ModelParseError";
  }
}

/** Validate before GLTFLoader sees the document: uploads must be self-contained. */
export function validateGlb(buffer: ArrayBuffer): void {
  const view = new DataView(buffer);
  if (buffer.byteLength < 20 || view.getUint32(0, true) !== 0x46546c67) {
    throw new ModelParseError("The file is not a binary GLB model.");
  }
  if (view.getUint32(4, true) !== 2 || view.getUint32(8, true) !== buffer.byteLength) {
    throw new ModelParseError("The GLB version or declared file length is invalid.");
  }
  let document: unknown;
  let offset = 12;
  while (offset < buffer.byteLength) {
    if (offset + 8 > buffer.byteLength) throw new ModelParseError("The GLB has a truncated chunk.");
    const length = view.getUint32(offset, true);
    const type = view.getUint32(offset + 4, true);
    if (length % 4 !== 0 || offset + 8 + length > buffer.byteLength) {
      throw new ModelParseError("The GLB has an invalid chunk length.");
    }
    if (offset === 12) {
      if (type !== 0x4e4f534a) throw new ModelParseError("The GLB is missing its JSON chunk.");
      try {
        document = JSON.parse(new TextDecoder().decode(new Uint8Array(buffer, offset + 8, length)));
      } catch {
        throw new ModelParseError("The GLB contains invalid JSON.");
      }
    }
    offset += 8 + length;
  }
  if (!document || typeof document !== "object") throw new ModelParseError("The GLB document is empty.");
  // Check extensions too. No model-authored remote/file URL may bypass the API's
  // asset authorization or contact a third party when a visitor opens a space.
  function checkUris(value: unknown): void {
    if (!value || typeof value !== "object") return;
    for (const [key, child] of Object.entries(value)) {
      if (key === "uri" && (typeof child !== "string" || !child.startsWith("data:"))) {
        throw new ModelParseError("The GLB references an external file. Export with embedded buffers and textures.");
      }
      checkUris(child);
    }
  }
  checkUris(document);
}

/** Column-major, affine scan-to-space matrix; translation occupies indices 12–14. */
export function scanMatrix(elements: readonly number[]): Matrix4 {
  if (elements.length !== 16 || !elements.every(Number.isFinite) ||
      elements[3] !== 0 || elements[7] !== 0 || elements[11] !== 0 || elements[15] !== 1) {
    throw new ModelParseError("The scan alignment must be a finite, affine 4×4 matrix.");
  }
  const matrix = new Matrix4().fromArray(elements);
  const scale = Math.max(...[0, 1, 2, 4, 5, 6, 8, 9, 10].map(i => Math.abs(elements[i]!)));
  const normalized = elements.map(value => value / scale);
  const determinant = normalized[0]! * (normalized[5]! * normalized[10]! - normalized[9]! * normalized[6]!)
    - normalized[4]! * (normalized[1]! * normalized[10]! - normalized[9]! * normalized[2]!)
    + normalized[8]! * (normalized[1]! * normalized[6]! - normalized[5]! * normalized[2]!);
  if (!Number.isFinite(determinant) || Math.abs(determinant) <= Number.EPSILON) {
    throw new ModelParseError("The scan alignment has zero scale and cannot be displayed.");
  }
  return matrix;
}

export interface GlbModel {
  /** Wrapper applies alignment while preserving every GLTF node transform. */
  object: Group;
  bounds: Box3;
  dispose(): void;
}

export function disposeModel(root: Group): void {
  const materials = new Set<Material>();
  const textures = new Set<Texture>();
  root.traverse((object) => {
    if (!(object instanceof Mesh)) return;
    object.geometry.dispose();
    for (const material of Array.isArray(object.material) ? object.material : [object.material]) {
      materials.add(material);
      for (const value of Object.values(material)) if (value instanceof Texture) textures.add(value);
    }
  });
  for (const material of materials) material.dispose();
  for (const texture of textures) {
    texture.dispose();
    const image = texture.source.data as { close?: () => void } | undefined;
    image?.close?.();
  }
}

export async function parseGlb(buffer: ArrayBuffer, transform: readonly number[]): Promise<GlbModel> {
  validateGlb(buffer);
  const matrix = scanMatrix(transform);
  const manager = new LoadingManager();
  let resourceFailed = false;
  manager.onError = () => { resourceFailed = true; };
  manager.setURLModifier((url) => {
    // GLTFLoader creates blob URLs for embedded image bufferViews.
    if (!url.startsWith("blob:") && !url.startsWith("data:")) {
      throw new ModelParseError("External GLB resources are not allowed.");
    }
    return url;
  });
  const gltf = await new GLTFLoader(manager).parseAsync(buffer, "");
  const object = new Group();
  object.matrixAutoUpdate = false;
  object.matrix.copy(matrix);
  object.add(gltf.scene);
  try {
    if (resourceFailed) throw new ModelParseError("An embedded texture or buffer could not be decoded. Re-export the GLB with valid embedded resources.");
    let vertices = 0;
    object.traverse((child) => {
      if (!(child instanceof Mesh)) return;
      const positions = child.geometry.getAttribute("position");
      if (!positions) return;
      vertices += positions.count;
      for (let i = 0; i < positions.count; i++) {
        if (![positions.getX(i), positions.getY(i), positions.getZ(i)].every(Number.isFinite)) {
          throw new ModelParseError("The GLB has invalid vertex coordinates.");
        }
      }
    });
    object.updateMatrixWorld(true);
    const bounds = new Box3().setFromObject(object);
    if (!vertices || bounds.isEmpty() || ![...bounds.min.toArray(), ...bounds.max.toArray()].every(Number.isFinite)) {
      throw new ModelParseError("The GLB has no usable mesh geometry.");
    }
    return { object, bounds, dispose: () => disposeModel(object) };
  } catch (error) {
    disposeModel(object);
    throw error;
  }
}
import { useEffect, useState } from "react";
import { findRoute, savedRoute, type Route } from "../lib/navigation";
import { nodeLabel, request, send, type Graph, type SavedPath, type Space, type User } from "../lib/space-api";

export default function NavigationPanel({ space, graph, paths, user, initialPath, onRoute, onSaved }: {
  space: Space; graph: Graph; paths: SavedPath[]; user: User | null; initialPath?: string;
  onRoute: (route: Route | null) => void; onSaved: () => void;
}) {
  const [start, setStart] = useState("");
  const [end, setEnd] = useState("");
  const [error, setError] = useState("");
  const [route, setRoute] = useState<Route | null>(null);
  const [saved, setSaved] = useState(initialPath ?? "");
  const [name, setName] = useState("");
  const [busy, setBusy] = useState(false);
  useEffect(() => setSaved(initialPath ?? ""), [initialPath]);
  useEffect(() => {
    setRoute(null); onRoute(null); setError("");
    if (!saved) return;
    const controller = new AbortController();
    request<{ path: SavedPath }>(`/api/paths/${encodeURIComponent(saved)}`, { signal: controller.signal })
      .then(({ path }) => { if (controller.signal.aborted) return; const result = savedRoute(graph, path); setRoute(result); onRoute(result); })
      .catch(e => { if (!controller.signal.aborted) setError(e.message); });
    return () => controller.abort();
  }, [saved, graph, onRoute]);
  function calculate() {
    setError("");
    try {
      const result = findRoute(graph, start, end);
      setRoute(result); onRoute(result);
      if (!result) setError("These locations are not connected in the allowed direction. Choose another start or destination.");
    } catch (e) { setRoute(null); onRoute(null); setError((e as Error).message); }
  }
  async function save() {
    if (!route || route.nodes.length < 2) return;
    setBusy(true); setError("");
    try {
      await send("/api/paths", "POST", { name, spaceId: space.id, visibility: space.visibility, nodeIds: route.nodes.map(n => n.id) });
      setName(""); onSaved();
    } catch (e) { setError((e as Error).message); }
    finally { setBusy(false); }
  }
  return <section className="editor-grid" aria-label="Navigation">
    <h2 className="text-lg font-bold">Find a route</h2>
    <label>Saved route<select value={saved} onChange={e => setSaved(e.target.value)}><option value="">Choose locations</option>{paths.map(p => <option key={p.id} value={p.id}>{p.name}</option>)}</select></label>
    {!saved && <>
      <label>Start<select value={start} onChange={e => { setStart(e.target.value); setRoute(null); onRoute(null); }}><option value="">Choose start</option>{graph.nodes.map(n => <option key={n.id} value={n.id}>{nodeLabel(n, graph)}</option>)}</select></label>
      <label>Destination<select value={end} onChange={e => { setEnd(e.target.value); setRoute(null); onRoute(null); }}><option value="">Choose destination</option>{graph.nodes.map(n => <option key={n.id} value={n.id}>{nodeLabel(n, graph)}</option>)}</select></label>
      <button className="action-button" onClick={calculate} disabled={!start || !end}>Show route</button>
    </>}
    {route && <div role="status"><p>{route.nodes.length === 1 ? "You are already at this location." : `${route.nodes.length - 1} connected segments`}</p>
      <ol className="list-inside list-decimal text-sm">{route.nodes.map((n, i) => <li key={`${n.id}-${i}`}>{nodeLabel(n, graph)}</li>)}</ol></div>}
    {error && <p role="alert" className="text-rust">{error}</p>}
    {!graph.nodes.length && <p>The owner has not added navigation locations yet.</p>}
    {user && !saved && route && route.nodes.length > 1 && <>
      <label>Route name<input value={name} maxLength={200} onChange={e => setName(e.target.value)} /></label>
      <button className="action-button" disabled={busy || !name.trim()} onClick={() => void save()}>Save route</button>
    </>}
  </section>;
}

