export { CAPTURE_WORKER_LOCK } from './locks';
const MAX_ATTEMPTS = 3;
type Job = typeof processingJobs.$inferSelect;
const hash = (bytes: Uint8Array) => createHash('sha256').update(bytes).digest('hex');
function errorMetadata(job: Job, code: string, message: string) {
  const previous = Array.isArray(job.metadata.errors) ? job.metadata.errors : [];
  return { ...job.metadata, errors: [...previous, { code, message, attempt: job.attemptCount,
    stage: job.stage, at: new Date().toISOString() }].slice(-20) };
}

export class CaptureWorker {
  constructor(private readonly options: {
    databaseUrl: string; captures: CaptureStorage; revisions: RevisionStorage; processor: CaptureProcessor;
    processors?: CaptureProcessor[];
    signal?: AbortSignal; heartbeatMs?: number; timeoutMs?: number;
  }) {}

  // Optional jobId is useful for targeted operational checks; the CLI drains FIFO by default.
  async runOnce(jobId?: string): Promise<{ state: 'busy' | 'idle' } | { state: 'processed'; jobId: string; status: 'succeeded' | 'failed' }> {
    const client = postgres(this.options.databaseUrl, { max: 1, prepare: false, idle_timeout: 0, max_lifetime: 0 });
    // This pool is private to one run, with one connection and no idle/lifetime recycling.
    // Use the full client so Drizzle retains postgres.js type parsers and transaction support.
    const connection = client;
    let locked = false;
    try {
      const [lock] = await connection`SELECT pg_try_advisory_lock(${CAPTURE_WORKER_LOCK}) AS acquired, pg_backend_pid() AS pid`;
      locked = lock.acquired;
      if (!locked) return { state: 'busy' };
      // An orphan CPU process can outlive a SIGKILLed parent. Its own session lock
      // prevents recovery/retry until that process exits (including its parent-pipe watchdog).
      const [cpu] = await connection`SELECT pg_try_advisory_lock(${CAPTURE_CPU_LOCK}) AS acquired`;
      if (!cpu.acquired) return { state: 'busy' };
      await connection`SELECT pg_advisory_unlock(${CAPTURE_CPU_LOCK})`;
      const pid = Number(lock.pid);
      const db = drizzle(connection);
      // Never steal work on lease expiry alone. This session lock proves no compliant worker owns it.
      const interrupted = await db.select().from(processingJobs).where(and(eq(processingJobs.status, 'running'), eq(processingJobs.jobType, 'capture')));
      for (const job of interrupted) {
        await db.update(processingJobs).set({
          status: job.attemptCount >= MAX_ATTEMPTS ? 'failed' : 'queued',
          stage: job.attemptCount >= MAX_ATTEMPTS ? 'failed' : 'recovered', progress: 0,
          leaseToken: null, leaseExpiresAt: null, errorCode: 'WORKER_INTERRUPTED',
          completedAt: job.attemptCount >= MAX_ATTEMPTS ? new Date() : null, updatedAt: new Date(),
          metadata: errorMetadata(job, 'WORKER_INTERRUPTED', 'Previous worker stopped before committing a result'),
        }).where(and(eq(processingJobs.id, job.id), sql`pg_backend_pid() = ${pid}`));
      }
      const job = await db.transaction(async tx => {
        const [queued] = await tx.select().from(processingJobs).where(and(
          eq(processingJobs.status, 'queued'), eq(processingJobs.jobType, 'capture'),
          jobId ? eq(processingJobs.id, jobId) : undefined,
        )).orderBy(asc(processingJobs.createdAt), asc(processingJobs.id)).limit(1).for('update', { skipLocked: true });
        if (!queued) return null;
        const [running] = await tx.update(processingJobs).set({ status: 'running', stage: 'preparing', progress: 5,
          attemptCount: queued.attemptCount + 1, leaseToken: randomUUID(),
          leaseExpiresAt: sql`now() + interval '30 seconds'`, heartbeatAt: new Date(),
          startedAt: queued.startedAt ?? new Date(), completedAt: null, updatedAt: new Date(),
        }).where(and(eq(processingJobs.id, queued.id), sql`pg_backend_pid() = ${pid}`)).returning();
        if (!running) throw new Error('Worker database session changed');
        return running;
      });
      if (!job) return { state: 'idle' };
      const controller = new AbortController();
      const signal = AbortSignal.any([controller.signal, AbortSignal.timeout(this.options.timeoutMs ?? 300_000),
        ...(this.options.signal ? [this.options.signal] : [])]);
      const guard = and(eq(processingJobs.id, job.id), eq(processingJobs.status, 'running'),
        eq(processingJobs.leaseToken, job.leaseToken!), sql`pg_backend_pid() = ${pid}`);
      let heartbeat: Promise<void> = Promise.resolve();
      const timer = setInterval(() => {
        heartbeat = heartbeat.then(async () => {
          const rows = await db.update(processingJobs).set({ heartbeatAt: new Date(),
            leaseExpiresAt: sql`now() + interval '30 seconds'`, updatedAt: new Date(),
          }).where(guard).returning({ id: processingJobs.id });
          if (!rows.length) throw new Error('Worker lease is no longer owned');
        }).catch(() => { controller.abort(new ProcessingFailure('WORKER_SESSION_LOST', 'Worker database session was lost')); });
      }, this.options.heartbeatMs ?? 5000);
      let work: string | undefined;
      let currentStage = job.stage;
      try {
        const setStage = async (stage: string, progress: number) => {
          signal.throwIfAborted();
          const rows = await db.update(processingJobs).set({ stage, progress, updatedAt: new Date() })
            .where(guard).returning({ id: processingJobs.id });
          if (!rows.length) throw new ProcessingFailure('WORKER_SESSION_LOST', 'Worker no longer owns this job');
          currentStage = stage;
        };
        const processor = [this.options.processor, ...(this.options.processors ?? [])].find(adapter =>
          job.processorVersion === adapter.version && job.configuration.processorId === adapter.id);
        if (!processor) {
          throw new ProcessingFailure('PROCESSOR_UNAVAILABLE', 'Queued processor version is not available in this worker');
        }
        const [capture] = await db.select().from(captures).where(eq(captures.id, job.captureId));
        if (!capture || capture.status !== 'uploaded' || capture.manifestSha256 !== job.inputSha256) {
          throw new ProcessingFailure('INVALID_INPUT', 'Capture is not finalized or its input digest changed');
        }
        const manifest = captureManifest.parse(capture.manifest);
        const manifestBytes = Buffer.from(canonicalJson(manifest));
        if (hash(manifestBytes) !== job.inputSha256) throw new ProcessingFailure('INVALID_INPUT', 'Manifest digest changed');
        work = await mkdtemp(path.join(tmpdir(), 'not404-processing-'));
        const inputDir = path.join(work, 'input'), outputDir = path.join(work, 'output');
        await mkdir(inputDir, { mode: 0o700 });
        await mkdir(outputDir, { mode: 0o700 });
        for (const file of [{ path: 'manifest.json', byteSize: manifestBytes.length, sha256: job.inputSha256 }, ...manifest.files]) {
          signal.throwIfAborted();
          let bytes: Uint8Array;
          try { bytes = await this.options.captures.read(captureObjectKey(capture.id, file.path), file.byteSize); }
          catch { throw new ProcessingFailure('INVALID_INPUT', 'Capture file is missing or exceeds its declared size'); }
          if (bytes.length !== file.byteSize || hash(bytes) !== file.sha256) throw new ProcessingFailure('INVALID_INPUT', 'Capture file checksum changed');
          const destination = path.join(inputDir, file.path);
          await mkdir(path.dirname(destination), { recursive: true, mode: 0o700 });
          await writeFile(destination, bytes, { flag: 'wx', mode: 0o600 });
        }
        await setStage('processing', 25);
        await processor.process({ inputDir, outputDir, signal });
        signal.throwIfAborted();
        await setStage('validating', 80);
        const revisionId = randomUUID();
        const outputs = await this.options.revisions.publish(outputDir, revisionId);
        signal.throwIfAborted();
        await db.transaction(async tx => {
          const [current] = await tx.select().from(processingJobs).where(guard).for('update');
          if (!current) throw new ProcessingFailure('WORKER_SESSION_LOST', 'Worker no longer owns this job');
          await tx.select({ id: captures.id }).from(captures).where(eq(captures.id, capture.id)).for('update');
          const [latest] = await tx.select({ number: sql<number>`coalesce(max(${scanRevisions.revision}), 0)` })
            .from(scanRevisions).where(eq(scanRevisions.captureId, capture.id));
          const scene = outputs.files.find(file => file.path === 'scene.glb');
          if (!scene) throw new ProcessingFailure('INVALID_OUTPUT', 'Scene output is missing');
          await tx.insert(scanRevisions).values({ id: revisionId, captureId: capture.id, spaceId: capture.spaceId,
            processingJobId: job.id, revision: Number(latest.number) + 1, objectKey: scene.objectKey,
            outputSha256: scene.sha256, transform: identityTransform,
            metadata: { files: outputs.files, report: outputs.report, processor: { id: processor.id, version: processor.version },
              inputSha256: job.inputSha256, alignmentVerified: false, coordinateSystem: manifest.coordinateSystem },
          });
          const rows = await tx.update(processingJobs).set({ status: 'succeeded', stage: 'complete', progress: 100,
            completedAt: new Date(), leaseToken: null, leaseExpiresAt: null, errorCode: null, updatedAt: new Date(),
          }).where(guard).returning({ id: processingJobs.id });
          if (!rows.length) throw new ProcessingFailure('WORKER_SESSION_LOST', 'Worker lost ownership before commit');
        });
        return { state: 'processed', jobId: job.id, status: 'succeeded' };
      } catch (error) {
        const code = error instanceof ProcessingFailure ? error.code : signal.aborted ? 'PROCESSING_ABORTED' : 'PROCESSOR_FAILED';
        const message = error instanceof ProcessingFailure ? error.message : 'Capture processing failed before a valid revision was committed';
        const rows = await db.update(processingJobs).set({ status: 'failed', stage: 'failed', errorCode: code,
          metadata: errorMetadata({ ...job, stage: currentStage }, code, message), completedAt: new Date(), updatedAt: new Date(),
          leaseToken: null, leaseExpiresAt: null,
        }).where(guard).returning({ id: processingJobs.id });
        if (!rows.length) throw new Error('Worker lost ownership; job remains durable for recovery');
        return { state: 'processed', jobId: job.id, status: 'failed' };
      } finally {
        clearInterval(timer);
        await heartbeat;
        if (work) await rm(work, { recursive: true, force: true });
      }
    } finally {
      try { if (locked) await connection`SELECT pg_advisory_unlock(${CAPTURE_WORKER_LOCK})`; }
      finally { await client.end(); }
    }
  }
}

import { spawn } from 'node:child_process';
import { createHash } from 'node:crypto';
import { lstat, readFile, readdir, rename, realpath, rmdir } from 'node:fs/promises';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { canonicalJson, captureManifest, validateFrameReferences } from '../capture/contract';
import { ProcessingFailure, type CaptureProcessor } from './processor';
import { CPU_PROCESSOR, processorTimeout } from './selection';
import { CAPTURE_CPU_LOCK } from './locks';

const CLI = fileURLToPath(new URL('../../../../../apps/capture/processor/cli.mjs', import.meta.url));
const RUNNER = fileURLToPath(new URL('./cpu-runner.mjs', import.meta.url));
const required = ['master.glb', 'scene.glb', 'preview.jpg', 'report.json'];
const allowed = [...required, 'scene.ply'];
const sha = (bytes: Uint8Array | string) => createHash('sha256').update(bytes).digest('hex');

async function boundedBytes(directory: string, filename: string, limit: number) {
  const file = path.join(directory, filename), stat = await lstat(file);
  if (!stat.isFile() || stat.isSymbolicLink() || stat.size <= 0 || stat.size > limit) throw new Error('Invalid file');
  const bytes = await readFile(file);
  if (bytes.length !== stat.size || bytes.length > limit) throw new Error('File changed');
  return bytes;
}

export class CpuCaptureProcessor implements CaptureProcessor {
  readonly id = CPU_PROCESSOR.id;
  readonly version = CPU_PROCESSOR.version;
  constructor(private readonly options: {
    databaseUrl: string; cliPath?: string; timeoutMs?: number; killGraceMs?: number;
  }) {
    if (process.platform === 'win32') throw new Error('CPU processor supervision requires POSIX (Linux/macOS)');
    if (!options.databaseUrl) throw new Error('CPU processor requires a session-preserving database connection');
    for (const n of [options.timeoutMs ?? 300_000, options.killGraceMs ?? 1000]) {
      if (!Number.isSafeInteger(n) || n < 1 || n > 3_600_000) throw new Error('Invalid CPU processor deadline');
    }
  }
  async process({ inputDir, outputDir, signal }: Parameters<CaptureProcessor['process']>[0]) {
    signal.throwIfAborted();
    const manifest = captureManifest.parse(JSON.parse((await boundedBytes(inputDir, 'manifest.json', 2 * 1024 * 1024)).toString()));
    const frames = validateFrameReferences(JSON.parse((await boundedBytes(inputDir, 'frames.json', 2 * 1024 * 1024)).toString()), manifest);
    // Worker owns this empty parent; CLI publishes atomically to an absent child destination.
    if ((await readdir(outputDir)).length) throw new ProcessingFailure('INVALID_OUTPUT', 'Output workspace must be empty');
    const destination = path.join(outputDir, 'cpu-result');
    let cli: string;
    try { cli = await realpath(path.resolve(this.options.cliPath ?? CLI)); if (!(await lstat(cli)).isFile()) throw new Error('Not a CLI file'); }
    catch { throw new ProcessingFailure('PROCESSOR_UNAVAILABLE', 'CPU processor CLI is not installed'); }
    await this.run(cli, [ '--input', inputDir, '--output', destination, '--expected-capture-id', manifest.captureId ], signal);
    signal.throwIfAborted();
    try {
      const directory = await lstat(destination);
      if (!directory.isDirectory() || directory.isSymbolicLink()) throw new Error('Unsafe output');
      const names = await readdir(destination);
      if (required.some(name => !names.includes(name)) || names.some(name => !allowed.includes(name))) throw new Error('Invalid inventory');
      const report = JSON.parse((await boundedBytes(destination, 'report.json', 2 * 1024 * 1024)).toString());
      if (report.captureId !== manifest.captureId || report.mock === true ||
          report.sourceManifestSha256 !== sha(canonicalJson(manifest)) ||
          canonicalJson(report.coordinateSystem) !== canonicalJson(manifest.coordinateSystem) ||
          canonicalJson(report.entrancePose) !== canonicalJson(manifest.entrancePose) ||
          canonicalJson(report.frames) !== canonicalJson(frames.frames) ||
          !report.assets || typeof report.assets !== 'object' || Array.isArray(report.assets) ||
          Object.keys(report.assets).length !== names.length - 1) throw new Error('Invalid provenance');
      for (const name of names.filter(name => name !== 'report.json')) {
        const bytes = await boundedBytes(destination, name, 32 * 1024 * 1024);
        const entry = report.assets[name];
        if (!entry || entry.byteSize !== bytes.length || entry.sha256 !== sha(bytes)) throw new Error('Invalid output checksum');
      }
      for (const name of names) await rename(path.join(destination, name), path.join(outputDir, name));
      // Empty result directory must not reach the independent revision inventory validator.
      await rmdir(destination);
    } catch { throw new ProcessingFailure('INVALID_OUTPUT', 'CPU output inventory, checksums or provenance are invalid'); }
    // LocalRevisionStorage independently validates GLB/JPEG/PLY formats and stores immutable 0600 bytes.
  }

  private async run(cli: string, args: string[], signal: AbortSignal) {
    signal.throwIfAborted();
    await new Promise<void>((resolve, reject) => {
      const child = spawn(process.execPath, [RUNNER, cli, ...args], {
        detached: true, shell: false, stdio: ['ignore', 'pipe', 'pipe', 'pipe'],
        env: { NODE_ENV: process.env.NODE_ENV ?? 'production', PATH: process.env.PATH, TMPDIR: process.env.TMPDIR, TZ: process.env.TZ,
          LIDAR_PARENT_PID: String(process.pid), LIDAR_CPU_LOCK: String(CAPTURE_CPU_LOCK),
          LIDAR_HARD_TIMEOUT_MS: String((this.options.timeoutMs ?? processorTimeout()) + (this.options.killGraceMs ?? 1000) + 2000),
          LIDAR_GUARD_DATABASE_URL: this.options.databaseUrl },
      });
      // Drain, never buffer or persist arbitrary processor stdout/stderr.
      child.stdout?.resume(); child.stderr?.resume();
      let failure: ProcessingFailure | undefined;
      let escalation: ReturnType<typeof setTimeout> | undefined;
      const kill = (kind: NodeJS.Signals) => {
        if (!child.pid) return;
        try { process.kill(-child.pid, kind); }
        catch (error) { if ((error as NodeJS.ErrnoException).code !== 'ESRCH') failure ??= new ProcessingFailure('PROCESSOR_STOP_FAILED', 'Unable to stop processor process group'); }
      };
      const stop = (reason: ProcessingFailure) => {
        if (failure) return;
        failure = reason; kill('SIGTERM');
        escalation = setTimeout(() => kill('SIGKILL'), this.options.killGraceMs ?? 1000);
      };
      const aborted = () => stop(signal.reason instanceof ProcessingFailure ? signal.reason :
        new ProcessingFailure(signal.reason?.name === 'TimeoutError' ? 'PROCESSOR_TIMEOUT' : 'PROCESSING_ABORTED',
          signal.reason?.name === 'TimeoutError' ? 'CPU processing timed out' : 'CPU processing was cancelled'));
      signal.addEventListener('abort', aborted, { once: true });
      const timeout = setTimeout(() => stop(new ProcessingFailure('PROCESSOR_TIMEOUT', 'CPU processing timed out')),
        this.options.timeoutMs ?? processorTimeout());
      child.on('error', () => { failure ??= new ProcessingFailure('PROCESSOR_START_FAILED', 'CPU processor could not be started'); });
      child.once('close', (code, exitSignal) => {
        clearTimeout(timeout); clearTimeout(escalation); signal.removeEventListener('abort', aborted);
        // close means termination and closed stdio; no job failure/retry is acknowledged earlier.
        if (failure) { reject(failure); return; }
        if (exitSignal) { reject(new ProcessingFailure('PROCESSOR_SIGNAL', 'CPU processor terminated unexpectedly')); return; }
        if (code === 0) { resolve(); return; }
        const reason: Record<number, [string, string]> = {
          1: ['PROCESSOR_FAILED', 'CPU processing failed'], 2: ['INVALID_INPUT', 'CPU processor rejected the capture'],
          64: ['PROCESSOR_USAGE', 'CPU processor configuration is invalid'], 75: ['WORKER_INTERRUPTED', 'CPU processor lost its parent or database session'],
        };
        const [errorCode, message] = reason[code ?? -1] ?? ['PROCESSOR_EXIT', 'CPU processor exited unsuccessfully'];
        reject(new ProcessingFailure(errorCode, message));
      });
      if (signal.aborted) aborted();
    });
  }
}
import { copyFile, mkdir, writeFile } from 'node:fs/promises';
import path from 'node:path';
import { MOCK_PROCESSOR } from './selection';

export const DEFAULT_PROCESSOR = MOCK_PROCESSOR;
export class ProcessingFailure extends Error {
  constructor(readonly code: string, message: string) { super(message); }
}

export interface CaptureProcessor {
  readonly id: string;
  readonly version: string;
  // The CLI adapter maps these directories to --input/--output without a shell.
  // It must stop its child process on abort and resolve only after the child has exited.
  process(options: { inputDir: string; outputDir: string; signal: AbortSignal }): Promise<void>;
}

export class MockCaptureProcessor implements CaptureProcessor {
  readonly id = DEFAULT_PROCESSOR.id;
  readonly version = DEFAULT_PROCESSOR.version;
  async process({ inputDir, outputDir, signal }: Parameters<CaptureProcessor['process']>[0]) {
    signal.throwIfAborted();
    await mkdir(outputDir, { recursive: true, mode: 0o700 });
    for (const [source, destination] of [
      ['source.glb', 'master.glb'], ['source.glb', 'scene.glb'],
      ['points.ply', 'scene.ply'], ['preview.jpg', 'preview.jpg'],
    ]) {
      signal.throwIfAborted();
      await copyFile(path.join(inputDir, source), path.join(outputDir, destination));
    }
    await writeFile(path.join(outputDir, 'report.json'), JSON.stringify({
      version: 1, processor: { id: this.id, version: this.version }, mock: true,
      warnings: ['Synthetic copy processor: no mesh processing, alignment or walkability verification.'],
    }), { mode: 0o600 });
    signal.throwIfAborted();
  }
}

import { z } from 'zod';
import { transform } from '../api/scans';

export const MAX_CAPTURE_FILE_BYTES = 32 * 1024 * 1024;
export const MAX_CAPTURE_BYTES = 256 * 1024 * 1024;
export const MAX_CAPTURE_JSON_BYTES = 2 * 1024 * 1024;
export const MAX_CAPTURE_FRAMES = 1000;
export const REQUIRED_CAPTURE_FILES = ['source.glb', 'points.ply', 'frames.json', 'preview.jpg'] as const;
const frameId = z.string().regex(/^[A-Za-z0-9][A-Za-z0-9_-]{0,127}$/).refine(value => value === value.trim());

// No decoding/normalization: reject ambiguous paths rather than trying to repair them.
export const capturePath = z.string().max(160).refine(value =>
  value === value.trim() && ((REQUIRED_CAPTURE_FILES as readonly string[]).includes(value) ||
  /^frames\/[A-Za-z0-9][A-Za-z0-9_-]{0,127}\.jpg$/.test(value)), 'Unsupported or unsafe capture path');
export const fileDigest = z.object({
  byteSize: z.number().int().positive().max(MAX_CAPTURE_FILE_BYTES),
  sha256: z.string().length(64).regex(/^[0-9a-f]{64}$/),
}).strict();

export const captureManifest = z.object({
  version: z.literal(1), captureId: z.uuid(),
  device: z.object({ model: z.string().min(1).max(200), osVersion: z.string().min(1).max(100) }).strict(),
  coordinateSystem: z.object({
    units: z.literal('metres'), upAxis: z.literal('Y'), handedness: z.literal('right'),
    matrixLayout: z.literal('column-major'), poseConvention: z.literal('camera-to-capture'),
  }).strict(),
  entrancePose: transform,
  capturedAt: z.iso.datetime({ offset: true }).optional(),
  trackingWarnings: z.array(z.string().min(1).max(1000)).max(100).default([]),
  files: z.array(fileDigest.extend({ path: capturePath }).strict()).min(5).max(MAX_CAPTURE_FRAMES + 4),
}).strict().superRefine((manifest, ctx) => {
  const paths = new Set(manifest.files.map(file => file.path));
  if (paths.size !== manifest.files.length) ctx.addIssue({ code: 'custom', message: 'Duplicate file paths' });
  for (const required of REQUIRED_CAPTURE_FILES) {
    if (!paths.has(required)) ctx.addIssue({ code: 'custom', message: `Missing required file: ${required}` });
  }
  if (manifest.files.reduce((sum, file) => sum + file.byteSize, 0) > MAX_CAPTURE_BYTES) {
    ctx.addIssue({ code: 'custom', message: 'Capture exceeds 256 MiB' });
  }
  const frames = manifest.files.find(file => file.path === 'frames.json');
  if (frames && frames.byteSize > MAX_CAPTURE_JSON_BYTES) {
    ctx.addIssue({ code: 'custom', message: 'frames.json exceeds 2 MiB' });
  }
});

export const captureRegistration = z.object({ spaceId: z.uuid(), manifest: captureManifest }).strict();
export type CaptureManifest = z.infer<typeof captureManifest>;
export type FileDigest = z.infer<typeof fileDigest>;

export const captureFrameIndex = z.object({
  version: z.literal(1), captureId: z.uuid(),
  frames: z.array(z.object({
    id: frameId, imagePath: capturePath, cameraPose: transform,
    timestampSeconds: z.number().finite().nonnegative(),
    width: z.number().int().positive().max(32768), height: z.number().int().positive().max(32768),
    intrinsics: z.object({
      fx: z.number().finite().positive(), fy: z.number().finite().positive(),
      cx: z.number().finite(), cy: z.number().finite(),
    }).strict().optional(),
  }).strict()).min(1).max(MAX_CAPTURE_FRAMES),
}).strict().superRefine((index, ctx) => {
  if (new Set(index.frames.map(frame => frame.id)).size !== index.frames.length) {
    ctx.addIssue({ code: 'custom', message: 'Duplicate frame IDs' });
  }
  for (const frame of index.frames) {
    if (frame.imagePath !== `frames/${frame.id}.jpg`) {
      ctx.addIssue({ code: 'custom', message: 'Frame imagePath must match its stable ID' });
    }
  }
});

export function validateFrameReferences(value: unknown, manifest: CaptureManifest) {
  return captureFrameIndex.superRefine((index, ctx) => {
    if (index.captureId !== manifest.captureId) ctx.addIssue({ code: 'custom', message: 'Frame capture ID does not match manifest' });
    const images = new Set(manifest.files.filter(file => file.path.startsWith('frames/')).map(file => file.path));
    if (index.frames.length !== images.size || index.frames.some(frame => !images.has(frame.imagePath))) {
      ctx.addIssue({ code: 'custom', message: 'Every manifest frame image must have exactly one frame reference' });
    }
  }).parse(value);
}

// Normalize object key ordering for retry identity, while retaining array order.
export function canonicalJson(value: unknown): string {
  if (Array.isArray(value)) return `[${value.map(canonicalJson).join(',')}]`;
  if (value !== null && typeof value === 'object') {
    return `{${Object.entries(value).filter(([, v]) => v !== undefined).sort(([a], [b]) => a < b ? -1 : a > b ? 1 : 0)
      .map(([key, v]) => `${JSON.stringify(key)}:${canonicalJson(v)}`).join(',')}}`;
  }
  return JSON.stringify(value);
}
# LiDAR capture handoff

Anish owns the iPhone exporter and CPU processor. Sam can exercise his worker against the checked-in [synthetic bundle](../../../fixtures/lidar-native-capture/manifest.json). It contains a two-metre square wall at Z = −2 m, a colored point cloud and two generated JPEG views. The original Swift-generated assets use an adapted version 1 manifest and frame index; see the [compatibility runbook](../../../docs/lidar-contract-compatibility.md) for provenance and the macOS exporter check. No Apple tooling is required on the worker.

## Run the fixture

From the repository root with Node.js 22.12+ and npm, run:

```sh
npm ci --prefix apps/capture/processor
workdir=$(mktemp -d)
./process_lidar_capture --input fixtures/lidar-native-capture --output "$workdir/revision" \
  --expected-capture-id 6d8c1359-2480-4493-89b8-39be20cc6fc9
cat "$workdir/revision/report.json"
npm test --prefix apps/capture/processor
```

The command uses CPU and local files. The fixture produces 200 triangles in `master.glb`, 100 in the mobile `scene.glb`, and 121 RGB points in `scene.ply`. Both models retain the two-metre span and embedded wall texture. The revision also contains a point-rendered `preview.jpg` and `report.json`. The report gives asset hashes and sizes, capture ID, source manifest hash, coordinate system, entrance pose, tracking warnings, and each original frame ID, relative path, timestamp and pose.

## Export on iPhone

Record a LiDAR surface scan in Path Capture and stop to save it. Recording works offline. Open the saved scan under **LiDAR upload bundle**, tap **Prepare LiDAR bundle**, then **Share LiDAR bundle** to save or transfer the ZIP. The ZIP contains a `capture/` directory. The scanner’s existing complete archive also includes private video, motion and depth buffers. Use the dedicated LiDAR bundle for this handoff.

A saved scan needs triangles, colored points and at least one tracked JPEG. Older compatible saved takes can be packaged with the same action. The manifest records an unknown device model when the original take predates device identification.

## Bundle version 1

| Path | Meaning |
| --- | --- |
| `manifest.json` | Stable device/take UUID, UTC capture time, device, coordinates, entrance pose, warnings, and one relative path, byte count and SHA-256 per payload file. |
| `source.glb` | Embedded triangle mesh. The scanner applies each ARKit anchor transform once when exporting its vertices to scan-world coordinates. |
| `points.ply` | Binary little-endian XYZ float32 and RGB uint8 in the same world frame. |
| `frames.json`, `frames/*.jpg` | Selected unrotated JPEGs. Each record has a capture-local ID derived from the recorded photo number, relative path, seconds from the first AR frame, and a camera-to-world transform. |
| `preview.jpg` | First selected camera frame for private intake. The worker renders a separate revision preview from the points. |

Positions are metres in ARKit's right-handed, +Y-up world. Camera forward is −Z in camera space. Matrices are column-major with translation at indices 12–14. The entrance pose is the **first normally tracked camera pose**. A venue organizer can identify which physical doorway that corresponds to. The worker preserves the coordinate frame and uses the source mesh's materials, textures and classification attributes. Its master welds matching vertices. Its mobile copy targets half the triangles per surface group with 32 or more triangles, locks group borders and limits geometric error to 0.001 of mesh extent. Small or constrained groups can retain their original count.

## Sam's worker

1. Register the device UUID and manifest for the authenticated owner. Materialize the finalized files into a worker-owned input directory. Finish all writes before starting the processor. Point `--input` at the directory containing `manifest.json`. Pass the manifest device UUID (not the database capture UUID) as `--expected-capture-id`.
2. Supply a fresh revision directory name under an existing local parent. Exit **0** means all five files are ready. Exit **2** means the input was missing, invalid or unprocessable. Exit **1** means an output, filesystem or runtime failure. Exit **64** means CLI usage was invalid. The backend adapter must store bounded, sanitized failure diagnostics. A complete revision appears with a single rename and an existing revision is preserved.
3. Store source frames privately. Keep the capture ID with each local frame ID when addressing it across captures. For example, `frame-0007` maps to `frames/frame-0007.jpg` at 1.25 s in this fixture. Sam assigns the immutable revision ID and binds that ID to the route and Gemini cue. The CLI creates local files. Publication, approval, ownership checks, and storage are handled by the backend.

The processor verifies file inventory, hashes, byte sizes, readable JPEGs, pose and frame references, embedded triangle GLB and native PLY. The intake accepts up to 1,000 selected frames (32 MiB/file, 2 MiB frame index) and 256 MiB per bundle. Run a physical LiDAR trial for scale, recognizable landmarks and actual mobile load time.

To exercise the complete UI-to-worker handoff on a Mac, run the following from the iOS bundle checkout with a booted simulator. Pass the absolute path to the installed worker checkout’s executable:

```sh
./scripts/check-ios-scanner.sh <booted-simulator-UDID> /path/to/worker/process_lidar_capture
```

The script generates the synthetic take through the Swift geometry exporter, opens it in Scan Review, prepares the ZIP, and processes its extracted contents.
import { useEffect, useState, type FormEvent } from "react";
import { Link } from "react-router";
import { alignmentControls, alignmentMatrix, calibrationScale, IDENTITY } from "../lib/alignment";
import { coordinates, nodeLabel, request, scanAligned, send, type Graph, type NavNode, type Position, type SavedPath, type Scan, type Space } from "../lib/space-api";

export interface PickedPoint { scanId: string; point: Position; localPoint: Position }
const zero = { x: 0, y: 0, z: 0 };

function VectorFields({ label, value, onChange }: { label: string; value: Position; onChange: (v: Position) => void }) {
  return <fieldset><legend className="text-sm">{label}</legend><div className="grid grid-cols-3 gap-2">{(["x", "y", "z"] as const).map(axis =>
    <label key={axis}>{axis.toUpperCase()}<input aria-label={`${label} ${axis}`} type="number" step="any" required value={value[axis]} onChange={e => onChange({ ...value, [axis]: e.target.valueAsNumber })} /></label>)}</div></fieldset>;
}

export default function SpaceEditor({ space, scans, graph, paths, picked, onChanged }: {
  space: Space; scans: Scan[]; graph: Graph; paths: SavedPath[]; picked: PickedPoint | null; onChanged: () => void;
}) {
  const [selected, setSelected] = useState("");
  const [matrix, setMatrix] = useState(JSON.stringify(IDENTITY));
  const [scale, setScale] = useState(1);
  const [rotation, setRotation] = useState<Position>(zero);
  const [translation, setTranslation] = useState<Position>(zero);
  const [position, setPosition] = useState<Position>(zero);
  const [a, setA] = useState<PickedPoint | null>(null);
  const [b, setB] = useState<PickedPoint | null>(null);
  const [measured, setMeasured] = useState(1);
  const [calibration, setCalibration] = useState<Record<string, unknown> | undefined>();
  const [verified, setVerified] = useState(false);
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState("");
  const [notice, setNotice] = useState("");
  const [eventId, setEventId] = useState("");
  const selectedScan = scans.find(s => s.id === selected);
  const frame = coordinates(space);
  // Nodes explicitly tied to other scans do not freeze a new scan's alignment.
  const graphExists = graph.nodes.some(n => n.metadata?.scanId === selected || !n.metadata?.scanId);
  const unverifiedScans = scans.some(s => s.status === "ready" && s.format === "glb" && !scanAligned(s, space));
  useEffect(() => { setPosition(picked?.point ?? zero); }, [picked]);
  useEffect(() => {
    const values = selectedScan?.transform ?? IDENTITY;
    setMatrix(JSON.stringify(values)); setA(null); setB(null);
    const controls = alignmentControls(values);
    setScale(controls?.scale ?? 1); setRotation(controls?.rotation ?? zero); setTranslation(controls?.translation ?? zero);
    setVerified(selectedScan?.metadata.alignmentVerified === true);
    setCalibration(selectedScan?.metadata.calibration as Record<string, unknown> | undefined);
  }, [selectedScan]);
  async function perform(action: () => Promise<unknown>) {
    setBusy(true); setError(""); setNotice("");
    try { await action(); setNotice("Saved."); onChanged(); }
    catch (e) { setError((e as Error).message); }
    finally { setBusy(false); }
  }
  function transform(): number[] {
    const value: unknown = JSON.parse(matrix);
    if (!Array.isArray(value) || value.length !== 16 || !value.every(v => typeof v === "number" && Number.isFinite(v))) throw new Error("Enter a matrix containing 16 finite numbers.");
    return value as number[];
  }
  function metadata() {
    const result = { ...selectedScan?.metadata };
    delete result.calibration;
    return { ...result, coordinateSystem: { ...frame, calibrated: frame.units === "metres" && verified }, alignmentVerified: verified,
      ...(calibration ? { calibration } : {}) };
  }
  async function upload(event: FormEvent<HTMLFormElement>) {
    event.preventDefault(); const form = new FormData(event.currentTarget);
    await perform(async () => {
      const file = form.get("file");
      if (!(file instanceof File) || !file.size || file.size > 32 * 1024 * 1024) throw new Error("Choose a GLB file no larger than 32 MiB.");
      form.set("transform", JSON.stringify(transform())); form.set("metadata", JSON.stringify(metadata()));
      await request(`/api/spaces/${space.id}/scans`, { method: "POST", body: form });
    });
  }
  function calibrate() {
    setError("");
    try {
      if (!a || !b || a.scanId !== selected || b.scanId !== selected) throw new Error("Pick both reference points on the selected scan.");
      const next = calibrationScale(a.localPoint, b.localPoint, measured);
      const current = alignmentControls(transform());
      if (!current) throw new Error("Two-point calibration requires a uniform-scale alignment. Restore a uniform transform first.");
      setScale(next); setCalibration({ sourceDistance: measured / next, measuredDistanceMetres: measured, scale: next });
      setRotation(current.rotation); setTranslation(current.translation); setVerified(false);
      setMatrix(JSON.stringify(alignmentMatrix(next, current.rotation, current.translation)));
    } catch (e) { setError((e as Error).message); }
  }
  return <details className="border-t border-forest/20 pt-3"><summary className="cursor-pointer font-bold">Owner tools</summary>
    <div className="editor-grid mt-3">
      {error && <p role="alert" className="text-rust">{error}</p>}{notice && <p role="status">{notice}</p>}
      <details><summary className="cursor-pointer">Upload and align scans</summary><div className="editor-grid mt-3">
        <label>Scan<select value={selected} onChange={e => setSelected(e.target.value)}><option value="">Upload a new scan</option>{scans.map(s => <option key={s.id} value={s.id}>{s.name}</option>)}</select></label>
        {selectedScan && <label>Scan sharing<select disabled={busy} value={selectedScan.visibility} onChange={e => void perform(() => send(`/api/scans/${selected}`, "PATCH", { visibility: e.target.value }))}><option value="private">Private</option>{space.visibility === "public" && <option value="public">Public</option>}</select></label>}
        {graphExists && selectedScan && <p className="text-sm">Alignment is locked after navigation nodes are added. This keeps the recorded route in place.</p>}
        <fieldset disabled={busy || (graphExists && !!selectedScan)} className="editor-grid">
          <p className="text-sm">Align the floor and choose the space origin before adding locations. Coordinates use {frame.units === "metres" ? "metres" : "relative units"}.</p>
          <label>Uniform scale<input type="number" min="0.000001" step="any" value={scale} onChange={e => { setScale(e.target.valueAsNumber); }} /></label>
          <VectorFields label="Rotation in degrees" value={rotation} onChange={setRotation} />
          <VectorFields label="Position" value={translation} onChange={setTranslation} />
          <button className="secondary-button" onClick={() => { try { setMatrix(JSON.stringify(alignmentMatrix(scale, rotation, translation))); setCalibration(undefined); setVerified(false); setError(""); } catch (e) { setError((e as Error).message); } }}>Use these alignment values</button>
          <label>Scan-to-space matrix<textarea rows={4} value={matrix} onChange={e => { setMatrix(e.target.value); setCalibration(undefined); setVerified(false); }} /></label>
          {selectedScan && frame.units === "metres" && <div className="editor-grid">
            <p className="text-sm">Double-click two recognizable points on this scan. Enter the distance measured at the venue.</p>
            <button className="secondary-button" disabled={!picked || picked.scanId !== selected} onClick={() => setA(picked)}>Use picked point A{a ? " ✓" : ""}</button>
            <button className="secondary-button" disabled={!picked || picked.scanId !== selected} onClick={() => setB(picked)}>Use picked point B{b ? " ✓" : ""}</button>
            <label>Measured distance (metres)<input type="number" min="0.000001" step="any" value={measured} onChange={e => setMeasured(e.target.valueAsNumber)} /></label>
            <button className="secondary-button" disabled={!a || !b} onClick={calibrate}>Calculate scale</button>
          </div>}
        </fieldset>
        <label className="flex gap-2"><input type="checkbox" disabled={busy} checked={verified} onChange={e => setVerified(e.target.checked)} />I verified the floor is Y-up and the origin and {frame.units === "metres" ? "measured scale" : "relative alignment"} match this space.</label>
        {selectedScan && <button className="action-button" disabled={busy} onClick={() => void perform(() => send(`/api/scans/${selected}`, "PATCH", { transform: graphExists ? selectedScan.transform : transform(), metadata: metadata() }))}>{graphExists ? "Save alignment confirmation" : "Save scan alignment"}</button>}
        {!selectedScan && <form onSubmit={upload} className="editor-grid">
          <label>Scan name<input name="name" required maxLength={200} /></label>
          <label>Textured GLB<input name="file" type="file" accept=".glb,model/gltf-binary" required /></label>
          <label>Scan sharing<select name="visibility" defaultValue="private"><option value="private">Private</option>{space.visibility === "public" && <option value="public">Public</option>}</select></label>
          <button className="action-button" disabled={busy}>Upload GLB</button>
        </form>}
      </div></details>
      <details><summary className="cursor-pointer">Locations and connections</summary><div className="editor-grid mt-3">
        <p className="text-sm">Double-click a visible floor surface to pick a location, or enter coordinates. Add only connections you have checked by walking the route.</p>
        {unverifiedScans && <p className="text-sm text-rust">Verify and save every scan's alignment above before adding navigation locations.</p>}
        <form className="editor-grid" onSubmit={event => { event.preventDefault(); const data = new FormData(event.currentTarget); void perform(() => send(`/api/spaces/${space.id}/graph/nodes`, "POST", { ...position, metadata: { name: data.get("name"), ...(picked ? { scanId: picked.scanId } : {}) } })); }}>
          <label>Location name<input name="name" required maxLength={200} /></label>
          <VectorFields label="Location" value={position} onChange={setPosition} />
          <button className="action-button" disabled={busy || unverifiedScans}>Add location</button>
        </form>
        <form className="editor-grid" onSubmit={event => { event.preventDefault(); const data = new FormData(event.currentTarget); void perform(async () => {
          const from = graph.nodes.find(n => n.id === data.get("from")), to = graph.nodes.find(n => n.id === data.get("to"));
          if (!from || !to || from.id === to.id) throw new Error("Select two different locations.");
          const distance = Math.hypot(from.x - to.x, from.y - to.y, from.z - to.z);
          if (distance <= 0) throw new Error("The two locations occupy the same position.");
          await send(`/api/spaces/${space.id}/graph/edges`, "POST", { fromNodeId: from.id, toNodeId: to.id, distance, bidirectional: data.get("both") === "on" });
        }); }}>
          <NodeSelect label="Connect from" name="from" graph={graph} /><NodeSelect label="Connect to" name="to" graph={graph} />
          <label className="flex gap-2"><input type="checkbox" name="both" defaultChecked />Allow travel both ways</label>
          <button className="action-button" disabled={busy || graph.nodes.length < 2}>Add connection</button>
        </form>
        <form className="editor-grid" onSubmit={event => { event.preventDefault(); const data = new FormData(event.currentTarget); void perform(() => send("/api/destinations", "POST", { spaceId: space.id, nodeId: data.get("node"), name: data.get("name") })); }}>
          <label>Destination name<input name="name" required maxLength={200} /></label><NodeSelect label="Destination location" name="node" graph={graph} />
          <button className="action-button" disabled={busy || !graph.nodes.length}>Add destination</button>
        </form>
      </div></details>
      <details><summary className="cursor-pointer">Share this environment</summary><div className="editor-grid mt-3">
        <label>Space sharing<select value={space.visibility} disabled={busy} onChange={e => void perform(() => send(`/api/spaces/${space.id}`, "PATCH", { visibility: e.target.value }))}><option value="private">Private</option><option value="public">Public</option></select></label>
        <p className="text-sm">Public space links show only public scans. Change each intended scan's sharing above.</p>
        {space.visibility === "public" && <form className="editor-grid" onSubmit={event => { event.preventDefault(); const data = new FormData(event.currentTarget); void perform(async () => {
          const result = await send<{ event: { id: string } }>("/api/events", "POST", { name: data.get("name"), visibility: "public", spaceIds: [space.id], pathIds: paths.filter(p => p.visibility === "public").map(p => p.id), destinationIds: graph.destinations.map(d => d.id) }); setEventId(result.event.id);
        }); }}><label>Event name<input name="name" required maxLength={200} /></label><button disabled={busy} className="action-button">Create public event link</button></form>}
        {eventId && <Link className="underline" to={`/events/${eventId}`}>Open shared event</Link>}
      </div></details>
    </div>
  </details>;
}

function NodeSelect({ label, name, graph }: { label: string; name: string; graph: Graph }) {
  return <label>{label}<select name={name} required><option value="">Choose location</option>{graph.nodes.map((n: NavNode) => <option key={n.id} value={n.id}>{nodeLabel(n, graph)}</option>)}</select></label>;
}

import { z } from 'zod';
import { transform } from '../api/scans';

export const MAX_CAPTURE_FILE_BYTES = 32 * 1024 * 1024;
export const MAX_CAPTURE_BYTES = 256 * 1024 * 1024;
export const MAX_CAPTURE_JSON_BYTES = 2 * 1024 * 1024;
export const MAX_CAPTURE_FRAMES = 1000;
export const REQUIRED_CAPTURE_FILES = ['source.glb', 'points.ply', 'frames.json', 'preview.jpg'] as const;
const frameId = z.string().regex(/^[A-Za-z0-9][A-Za-z0-9_-]{0,127}$/).refine(value => value === value.trim());

// No decoding/normalization: reject ambiguous paths rather than trying to repair them.
export const capturePath = z.string().max(160).refine(value =>
  value === value.trim() && ((REQUIRED_CAPTURE_FILES as readonly string[]).includes(value) ||
  /^frames\/[A-Za-z0-9][A-Za-z0-9_-]{0,127}\.jpg$/.test(value)), 'Unsupported or unsafe capture path');
export const fileDigest = z.object({
  byteSize: z.number().int().positive().max(MAX_CAPTURE_FILE_BYTES),
  sha256: z.string().length(64).regex(/^[0-9a-f]{64}$/),
}).strict();

export const captureManifest = z.object({
  version: z.literal(1), captureId: z.uuid(),
  device: z.object({ model: z.string().min(1).max(200), osVersion: z.string().min(1).max(100) }).strict(),
  coordinateSystem: z.object({
    units: z.literal('metres'), upAxis: z.literal('Y'), handedness: z.literal('right'),
    matrixLayout: z.literal('column-major'), poseConvention: z.literal('camera-to-capture'),
  }).strict(),
  entrancePose: transform,
  capturedAt: z.iso.datetime({ offset: true }).optional(),
  trackingWarnings: z.array(z.string().min(1).max(1000)).max(100).default([]),
  files: z.array(fileDigest.extend({ path: capturePath }).strict()).min(5).max(MAX_CAPTURE_FRAMES + 4),
}).strict().superRefine((manifest, ctx) => {
  const paths = new Set(manifest.files.map(file => file.path));
  if (paths.size !== manifest.files.length) ctx.addIssue({ code: 'custom', message: 'Duplicate file paths' });
  for (const required of REQUIRED_CAPTURE_FILES) {
    if (!paths.has(required)) ctx.addIssue({ code: 'custom', message: `Missing required file: ${required}` });
  }
  if (manifest.files.reduce((sum, file) => sum + file.byteSize, 0) > MAX_CAPTURE_BYTES) {
    ctx.addIssue({ code: 'custom', message: 'Capture exceeds 256 MiB' });
  }
  const frames = manifest.files.find(file => file.path === 'frames.json');
  if (frames && frames.byteSize > MAX_CAPTURE_JSON_BYTES) {
    ctx.addIssue({ code: 'custom', message: 'frames.json exceeds 2 MiB' });
  }
});

export const captureRegistration = z.object({ spaceId: z.uuid(), manifest: captureManifest }).strict();
export type CaptureManifest = z.infer<typeof captureManifest>;
export type FileDigest = z.infer<typeof fileDigest>;

export const captureFrameIndex = z.object({
  version: z.literal(1), captureId: z.uuid(),
  frames: z.array(z.object({
    id: frameId, imagePath: capturePath, cameraPose: transform,
    timestampSeconds: z.number().finite().nonnegative(),
    width: z.number().int().positive().max(32768), height: z.number().int().positive().max(32768),
    intrinsics: z.object({
      fx: z.number().finite().positive(), fy: z.number().finite().positive(),
      cx: z.number().finite(), cy: z.number().finite(),
    }).strict().optional(),
  }).strict()).min(1).max(MAX_CAPTURE_FRAMES),
}).strict().superRefine((index, ctx) => {
  if (new Set(index.frames.map(frame => frame.id)).size !== index.frames.length) {
    ctx.addIssue({ code: 'custom', message: 'Duplicate frame IDs' });
  }
  for (const frame of index.frames) {
    if (frame.imagePath !== `frames/${frame.id}.jpg`) {
      ctx.addIssue({ code: 'custom', message: 'Frame imagePath must match its stable ID' });
    }
  }
});

export function validateFrameReferences(value: unknown, manifest: CaptureManifest) {
  return captureFrameIndex.superRefine((index, ctx) => {
    if (index.captureId !== manifest.captureId) ctx.addIssue({ code: 'custom', message: 'Frame capture ID does not match manifest' });
    const images = new Set(manifest.files.filter(file => file.path.startsWith('frames/')).map(file => file.path));
    if (index.frames.length !== images.size || index.frames.some(frame => !images.has(frame.imagePath))) {
      ctx.addIssue({ code: 'custom', message: 'Every manifest frame image must have exactly one frame reference' });
    }
  }).parse(value);
}

// Normalize object key ordering for retry identity, while retaining array order.
export function canonicalJson(value: unknown): string {
  if (Array.isArray(value)) return `[${value.map(canonicalJson).join(',')}]`;
  if (value !== null && typeof value === 'object') {
    return `{${Object.entries(value).filter(([, v]) => v !== undefined).sort(([a], [b]) => a < b ? -1 : a > b ? 1 : 0)
      .map(([key, v]) => `${JSON.stringify(key)}:${canonicalJson(v)}`).join(',')}}`;
  }
  return JSON.stringify(value);
}
import { spawn } from 'node:child_process';
import { createHash } from 'node:crypto';
import { lstat, readFile, readdir, rename, realpath, rmdir } from 'node:fs/promises';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { canonicalJson, captureManifest, validateFrameReferences } from '../capture/contract';
import { ProcessingFailure, type CaptureProcessor } from './processor';
import { CPU_PROCESSOR, processorTimeout } from './selection';
import { CAPTURE_CPU_LOCK } from './locks';

const CLI = fileURLToPath(new URL('../../../../../apps/capture/processor/cli.mjs', import.meta.url));
const RUNNER = fileURLToPath(new URL('./cpu-runner.mjs', import.meta.url));
const required = ['master.glb', 'scene.glb', 'preview.jpg', 'report.json'];
const allowed = [...required, 'scene.ply'];
const sha = (bytes: Uint8Array | string) => createHash('sha256').update(bytes).digest('hex');

async function boundedBytes(directory: string, filename: string, limit: number) {
  const file = path.join(directory, filename), stat = await lstat(file);
  if (!stat.isFile() || stat.isSymbolicLink() || stat.size <= 0 || stat.size > limit) throw new Error('Invalid file');
  const bytes = await readFile(file);
  if (bytes.length !== stat.size || bytes.length > limit) throw new Error('File changed');
  return bytes;
}

export class CpuCaptureProcessor implements CaptureProcessor {
  readonly id = CPU_PROCESSOR.id;
  readonly version = CPU_PROCESSOR.version;
  constructor(private readonly options: {
    databaseUrl: string; cliPath?: string; timeoutMs?: number; killGraceMs?: number;
  }) {
    if (process.platform === 'win32') throw new Error('CPU processor supervision requires POSIX (Linux/macOS)');
    if (!options.databaseUrl) throw new Error('CPU processor requires a session-preserving database connection');
    for (const n of [options.timeoutMs ?? 300_000, options.killGraceMs ?? 1000]) {
      if (!Number.isSafeInteger(n) || n < 1 || n > 3_600_000) throw new Error('Invalid CPU processor deadline');
    }
  }
  async process({ inputDir, outputDir, signal }: Parameters<CaptureProcessor['process']>[0]) {
    signal.throwIfAborted();
    const manifest = captureManifest.parse(JSON.parse((await boundedBytes(inputDir, 'manifest.json', 2 * 1024 * 1024)).toString()));
    const frames = validateFrameReferences(JSON.parse((await boundedBytes(inputDir, 'frames.json', 2 * 1024 * 1024)).toString()), manifest);
    // Worker owns this empty parent; CLI publishes atomically to an absent child destination.
    if ((await readdir(outputDir)).length) throw new ProcessingFailure('INVALID_OUTPUT', 'Output workspace must be empty');
    const destination = path.join(outputDir, 'cpu-result');
    let cli: string;
    try { cli = await realpath(path.resolve(this.options.cliPath ?? CLI)); if (!(await lstat(cli)).isFile()) throw new Error('Not a CLI file'); }
    catch { throw new ProcessingFailure('PROCESSOR_UNAVAILABLE', 'CPU processor CLI is not installed'); }
    await this.run(cli, [ '--input', inputDir, '--output', destination, '--expected-capture-id', manifest.captureId ], signal);
    signal.throwIfAborted();
    try {
      const directory = await lstat(destination);
      if (!directory.isDirectory() || directory.isSymbolicLink()) throw new Error('Unsafe output');
      const names = await readdir(destination);
      if (required.some(name => !names.includes(name)) || names.some(name => !allowed.includes(name))) throw new Error('Invalid inventory');
      const report = JSON.parse((await boundedBytes(destination, 'report.json', 2 * 1024 * 1024)).toString());
      if (report.captureId !== manifest.captureId || report.mock === true ||
          report.sourceManifestSha256 !== sha(canonicalJson(manifest)) ||
          canonicalJson(report.coordinateSystem) !== canonicalJson(manifest.coordinateSystem) ||
          canonicalJson(report.entrancePose) !== canonicalJson(manifest.entrancePose) ||
          canonicalJson(report.frames) !== canonicalJson(frames.frames) ||
          !report.assets || typeof report.assets !== 'object' || Array.isArray(report.assets) ||
          Object.keys(report.assets).length !== names.length - 1) throw new Error('Invalid provenance');
      for (const name of names.filter(name => name !== 'report.json')) {
        const bytes = await boundedBytes(destination, name, 32 * 1024 * 1024);
        const entry = report.assets[name];
        if (!entry || entry.byteSize !== bytes.length || entry.sha256 !== sha(bytes)) throw new Error('Invalid output checksum');
      }
      for (const name of names) await rename(path.join(destination, name), path.join(outputDir, name));
      // Empty result directory must not reach the independent revision inventory validator.
      await rmdir(destination);
    } catch { throw new ProcessingFailure('INVALID_OUTPUT', 'CPU output inventory, checksums or provenance are invalid'); }
    // LocalRevisionStorage independently validates GLB/JPEG/PLY formats and stores immutable 0600 bytes.
  }

  private async run(cli: string, args: string[], signal: AbortSignal) {
    signal.throwIfAborted();
    await new Promise<void>((resolve, reject) => {
      const child = spawn(process.execPath, [RUNNER, cli, ...args], {
        detached: true, shell: false, stdio: ['ignore', 'pipe', 'pipe', 'pipe'],
        env: { NODE_ENV: process.env.NODE_ENV ?? 'production', PATH: process.env.PATH, TMPDIR: process.env.TMPDIR, TZ: process.env.TZ,
          LIDAR_PARENT_PID: String(process.pid), LIDAR_CPU_LOCK: String(CAPTURE_CPU_LOCK),
          LIDAR_HARD_TIMEOUT_MS: String((this.options.timeoutMs ?? processorTimeout()) + (this.options.killGraceMs ?? 1000) + 2000),
          LIDAR_GUARD_DATABASE_URL: this.options.databaseUrl },
      });
      // Drain, never buffer or persist arbitrary processor stdout/stderr.
      child.stdout?.resume(); child.stderr?.resume();
      let failure: ProcessingFailure | undefined;
      let escalation: ReturnType<typeof setTimeout> | undefined;
      const kill = (kind: NodeJS.Signals) => {
        if (!child.pid) return;
        try { process.kill(-child.pid, kind); }
        catch (error) { if ((error as NodeJS.ErrnoException).code !== 'ESRCH') failure ??= new ProcessingFailure('PROCESSOR_STOP_FAILED', 'Unable to stop processor process group'); }
      };
      const stop = (reason: ProcessingFailure) => {
        if (failure) return;
        failure = reason; kill('SIGTERM');
        escalation = setTimeout(() => kill('SIGKILL'), this.options.killGraceMs ?? 1000);
      };
      const aborted = () => stop(signal.reason instanceof ProcessingFailure ? signal.reason :
        new ProcessingFailure(signal.reason?.name === 'TimeoutError' ? 'PROCESSOR_TIMEOUT' : 'PROCESSING_ABORTED',
          signal.reason?.name === 'TimeoutError' ? 'CPU processing timed out' : 'CPU processing was cancelled'));
      signal.addEventListener('abort', aborted, { once: true });
      const timeout = setTimeout(() => stop(new ProcessingFailure('PROCESSOR_TIMEOUT', 'CPU processing timed out')),
        this.options.timeoutMs ?? processorTimeout());
      child.on('error', () => { failure ??= new ProcessingFailure('PROCESSOR_START_FAILED', 'CPU processor could not be started'); });
      child.once('close', (code, exitSignal) => {
